 logic may perform memory accesses based on the extension's expected
 size. If the user provides a size smaller than what the extension
 requires, it results in an out-of-bounds read as reported by KASAN.

 This fix introduces a check to ensure match_size is at least as large
 as the extension's required compatsize. This covers matches, watchers,
 and targets, while maintaining compatibility with standard targets.

AFAIU this is relevant for matches that need to go though
match->compat_from_user() call.  Those that use plain memcpy with the
user-provided size are ok because the caller checks that size vs the
start of the next rule entry offset (which itself is checked vs. total
size copied from userspace).

The ->compat_from_user() callbacks assume they can read compatsize bytes,
so they need this extra check.

Based on an earlier patch from Luxiao Xu.

Fixes: 81e675c227ec ("netfilter: ebtables: add CONFIG_COMPAT support")
Reported-by: Yuan Tan <yuantan098@gmail.com>
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Reported-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Luxiao Xu <rakukuip@gmail.com>
Signed-off-by: Ren Wei <n05ec@lzu.edu.cn>
Reviewed-by: Fernando Fernandez Mancera <fmancera@suse.de>
Signed-off-by: Florian Westphal <fw@strlen.de>

Here is the root cause:
The function `compat_mtw_from_user()` lacks validation that the user-supplied `match_size`/`target_size` is at least the extension's required `compatsize`. The `->compat_from_user()` callbacks assume they can read `compatsize` bytes, so a smaller user-provided size leads to an out-of-bounds read.

Here is the patch:

+static bool match_size_ok(const struct xt_match *match, unsigned int match_size)
+{
+	u16 csize;
+
+	if (match->matchsize == -1) /* cannot validate ebt_among */
+		return true;
+
+	csize = match->compatsize ? : match->matchsize;
+
+	return match_size >= csize;
+}
+
+static bool tgt_size_ok(const struct xt_target *tgt, unsigned int tgt_size)
+{
+	u16 csize = tgt->compatsize ? : tgt->targetsize;
+
+	return tgt_size >= csize;
+}
+
 static int compat_mtw_from_user(const struct compat_ebt_entry_mwt *mwt,
 				enum compat_mwt compat_mwt,
 				struct ebt_entries_buf_state *state,
 				const unsigned char *base)
 {
 	char name[EBT_EXTENSION_MAXNAMELEN];
 	struct xt_match *match;
 	struct xt_target *wt;
 	void *dst = NULL;
 	int off, pad = 0;
 	unsigned int size_kern, match_size = mwt->match_size;

 	if (strscpy(name, mwt->u.name, sizeof(name)) < 0)
 		return -EINVAL;

 	if (state->buf_kern_start)
 		dst = state->buf_kern_start + state->buf_kern_offset;

 	switch (compat_mwt) {
 	case EBT_COMPAT_MATCH:
 		match = xt_request_find_match(NFPROTO_BRIDGE, name,
 					      mwt->u.revision);
 		if (IS_ERR(match))
 			return PTR_ERR(match);

+		if (!match_size_ok(match, match_size)) {
+			module_put(match->me);
+			return -EINVAL;
+		}
+
 		off = ebt_compat_match_offset(match, match_size);
 		if (dst) {
 			if (match->compat_from_user)
 				match->compat_from_user(dst, mwt->data);
 			else
 				memcpy(dst, mwt->data, match_size);
 		}

 		size_kern = match->matchsize;
 		if (unlikely(size_kern == -1))
 			size_kern = match_size;
 		module_put(match->me);
 		break;
 	case EBT_COMPAT_WATCHER:
 	case EBT_COMPAT_TARGET:
 		wt = xt_request_find_target(NFPROTO_BRIDGE, name,
 					    mwt->u.revision);
 		if (IS_ERR(wt))
 			return PTR_ERR(wt);
+
+		if (!tgt_size_ok(wt, match_size)) {
+			module_put(wt->me);
+			return -EINVAL;
+		}
+
 		off = xt_compat_target_offset(wt);

 		if (dst) {
 			if (wt->compat_from_user)
 				wt->compat_from_user(dst, mwt->data);
 			else
 				memcpy(dst, mwt->data, match_size);
 		}

 		size_kern = wt->targetsize;
 		module_put(wt->me);
 		break;

 	default:
 		return -EINVAL;
 	}

 	state->buf_kern_offset += match_size + off;
 	state->buf_user_offset += match_size;
 	pad = XT_ALIGN(size_kern) - size_kern;

 	if (pad > 0 && dst) {
 		if (WARN_ON(state->buf_kern_len <= pad))
 			return -EINVAL;
 		if (WARN_ON(state->buf_kern_offset - (match_size + off) + size_kern > state->buf_kern_len - pad))
 			return -EINVAL;
 		memset(dst + size_kern, 0, pad);
 	}
 	return off + match_size;
 }



